with valid as (select *, cost + stock_qty cost_plus_stock_qty from products where brand is not null) select date_trunc('month', launch_date) as activity_month, date_trunc('quarter', launch_date) as quarter_start, corr(cost, price) as corr_cost_price, count(case when brand = 'Stark' then 1 end) as stark_count from valid group by activity_month, quarter_start having count(case when brand = 'Stark' then 1 end) < 1000 order by stark_count nulls first
